21 |     struct UserInfo {
22 |         uint128 amount; // How many tokens the user has provided.
23 |         uint128 rewardDebt; // Reward debt. See explanation below.
24 |         //
25 |         // We do some fancy math here. Basically, any point in time, the amount of RADSs
26 |         // entitled to a user but is pending to be distributed is:
27 |         //
28 |         //   pending reward = (user.amount * pool.accumlatedConcurPerShare) - user.rewardDebt
29 |         //
30 |         // Whenever a user deposits or withdraws LP tokens to a pool. Here's what happens:
31 |         //   1. The pool's `accumlatedConcurPerShare` (and `lastRewardBlock`) gets updated.
32 |         //   2. User receives the pending reward sent to his/her address.
33 |         //   3. User's `amount` gets updated.
34 |         //   4. User's `rewardDebt` gets updated.
35 |     }
36 | 
