38 |     struct PoolInfo {
39 |         IERC20 depositToken; // Address of LP token contract.
40 |         uint allocPoint; // How many allocation points assigned to this pool. to distribute per block.
41 |         uint lastRewardBlock; // Last block number that distribution occurs.
42 |         uint accConcurPerShare; // Accumulated per share, times multiplier. See below.
43 |         uint16 depositFeeBP; // Deposit fee in basis points
44 |     }
45 | 
